      { q: "कर्मवाच्य का प्रयोग प्रायः कब किया जाता है?", options: ["जब कर्ता को विशेष महत्व देना हो", "जब क्रिया अकर्मक हो", "जब कर्ता अज्ञात या महत्वहीन हो", "जब वाक्य प्रश्नवाचक हो"], answer: 2, explain: "जैसे 'दुकान लूट ली गई' में लूटने वाला अज्ञात है, इसलिए कर्म को प्रधानता मिलती है।", level: 2 },

      { q: "'किसान द्वारा हल चलाया गया।' का कर्तृवाच्य है –", options: ["किसान ने हल चलाया।", "किसान हल चलाया गया।", "किसान को हल चलाना पड़ा।", "किसान से हल चलता है।"], answer: 0, explain: "कर्ता 'किसान' को प्रधान बनाकर 'ने' लगाने से कर्तृवाच्य बनता है।", level: 3 },
      { q: "निम्नलिखित में कौन-सा वाक्य भाववाच्य है?", options: ["रोटी खाई जाती है।", "वह गाता है।", "बच्चे से पढ़ा नहीं जाता।", "पत्र लिखा गया।"], answer: 2, explain: "अकर्मक क्रिया, 'से' सहित कर्ता और निषेध – ये भाववाच्य के लक्षण हैं।", level: 3 },
      { q: "'वह पत्र लिखती थी।' का कर्मवाच्य होगा –", options: ["उसके द्वारा पत्र लिखा गया।", "उसके द्वारा पत्र लिखा जाता था।", "उससे पत्र लिखी जाती थी।", "उसके द्वारा पत्र लिखे जाते हैं।"], answer: 1, explain: "भूतकाल की सतत/आभ्यासिक क्रिया 'लिखती थी' का रूप 'लिखा जाता था' होगा; कर्म 'पत्र' पुल्लिंग है।", level: 3 },
      { q: "'पुलिस ने चोर को पकड़ लिया।' का कर्मवाच्य है –", options: ["पुलिस द्वारा चोर को पकड़ा जाता है।", "चोर के द्वारा पुलिस पकड़ी गई।", "पुलिस से चोर पकड़ ली गई।", "पुलिस द्वारा चोर पकड़ लिया गया।"], answer: 3, explain: "कर्म 'चोर' पुल्लिंग एकवचन है और काल भूतकाल, इसलिए 'पकड़ लिया गया'।", level: 3 }
