    written: [
      { q: "वाच्य किसे कहते हैं?", a: "क्रिया के जिस रूपांतर से यह पता चले कि वाक्य में प्रधानता कर्ता, कर्म या भाव में से किसकी है, उसे वाच्य कहते हैं।\nकारण: वाच्य क्रिया का वह रूप है जो प्रधान तत्व बताता है।", marks: 1 },
      { q: "'सोहन ने चित्र बनाया।' का कर्मवाच्य लिखिए।", a: "सोहन द्वारा चित्र बनाया गया।\nकारण: कर्ता के साथ 'द्वारा' लगता है और क्रिया कर्म 'चित्र' के अनुसार होती है।", marks: 1 },
      { q: "भाववाच्य में क्रिया प्रायः कैसी होती है?", a: "अकर्मक क्रिया (प्रायः निषेधात्मक) होती है, और रूप पुल्लिंग, एकवचन, अन्य पुरुष रहता है।\nकारण: इसमें भाव ही प्रधान होता है, न कर्ता, न कर्म।", marks: 1 },
      { q: "वाच्य पहचानिए – 'किसान खेत जोतता है।'", a: "कर्तृवाच्य।\nकारण: कर्ता 'किसान' प्रधान है और क्रिया उसी के अनुसार है।", marks: 1 },
      { q: "कर्तृवाच्य और कर्मवाच्य में कोई दो अंतर लिखिए।", a: "(1) कर्तृवाच्य में कर्ता प्रधान होता है और क्रिया कर्ता के लिंग-वचन के अनुसार चलती है; कर्मवाच्य में कर्म प्रधान होता है और क्रिया कर्म के अनुसार चलती है।\n(2) कर्मवाच्य में कर्ता के साथ प्रायः 'से' या 'द्वारा' आता है तथा क्रिया में 'जाना' जुड़ता है।\nकारण: दोनों में प्रधान तत्व अलग है।", marks: 2 },
      { q: "भाववाच्य में बदलिए – (क) मैं नहीं चल सकता। (ख) वह बैठ नहीं सकती।", a: "(क) मुझसे चला नहीं जाता।\n(ख) उससे बैठा नहीं जाता।\nकारण: कर्ता के साथ 'से' लगाया गया और क्रिया अन्य पुरुष, पुल्लिंग, एकवचन 'जाता' रूप में रखी गई।", marks: 2 },
      { q: "कर्मवाच्य में बदलिए – (क) माली पौधों को सींचता है। (ख) बच्चों ने गीत गाया। (ग) मैंने पत्र लिखा।", a: "(क) माली द्वारा पौधे सींचे जाते हैं।\n(ख) बच्चों द्वारा गीत गाया गया।\n(ग) मेरे द्वारा पत्र लिखा गया।\nकारण: कर्म को कर्ता-स्थान पर रखा गया, कर्ता के साथ 'द्वारा' लगा और क्रिया कर्म के अनुसार 'जाना' सहित बदली।", marks: 3 },
      { q: "वाच्य पहचानकर कारण लिखिए – (क) पुस्तकालय में पुस्तकें पढ़ी जाती हैं। (ख) अध्यापक छात्रों को पढ़ाते हैं। (ग) बीमार से चला नहीं जाता।", a: "(क) कर्मवाच्य – क्रिया कर्म 'पुस्तकें' (स्त्रीलिंग, बहुवचन) के अनुसार है।\n(ख) कर्तृवाच्य – क्रिया कर्ता 'अध्यापक' के अनुसार है।\n(ग) भाववाच्य – अकर्मक क्रिया, निषेध और 'से' के साथ भाव की प्रधानता है।", marks: 3 }
    ]
