      { q: "'अट नहीं रही है' में 'अट नहीं रही' का आशय है –", options: ["वर्षा रुक रही है", "फूल मुरझा रहे हैं", "कवि उदास है", "शोभा समा नहीं रही, चारों ओर फैल रही है"], answer: 3, explain: "फागुन की शोभा इतनी अधिक है कि वह सब जगह छलक रही है।", level: 2 },
      { q: "फागुन की शोभा के वर्णन में कवि ने प्रकृति पर कौन-सा गुण आरोपित किया है?", options: ["निर्जीवता", "मानवीकरण (प्राकृतिक दृश्य में मानवीय भाव)", "भयानकता", "रहस्य"], answer: 1, explain: "कवि प्रकृति को जीवंत, भावनाओं से भरे रूप में प्रस्तुत करता है।", level: 2 },
      { q: "'उत्साह' कविता का मूल भाव है –", options: ["प्रकृति से भय", "समाज में नवचेतना और क्रांति का उत्साह", "उदासी", "पलायन"], answer: 1, explain: "कविता में जड़ता तोड़कर नव-निर्माण का उत्साह है।", level: 2 },

      { q: "'उत्साह' में कवि बादल को 'कवि' और 'नवजीवन वाले' कहकर संबोधित करता है। इसका आशय है –", options: ["बादल पढ़ाई करते हैं", "बादल निर्जन है", "बादल बोलता है", "बादल से नई कविता/नए सृजन की शक्ति की अपेक्षा"], answer: 3, explain: "कवि बादल से नई कविता और नवजीवन भरने की कामना करता है।", level: 3 },
      { q: "दोनों कविताओं में कवि की दृष्टि की समानता क्या है?", options: ["दोनों में प्रकृति को जीवन और ऊर्जा के स्रोत के रूप में देखा गया है", "दोनों में उदासी है", "दोनों में युद्ध है", "दोनों में उपदेश है"], answer: 0, explain: "एक में बादल, दूसरी में फागुन – दोनों प्रकृति की जीवनदायिनी शक्ति दिखाते हैं।", level: 3 },
      { q: "गर्मी की तपन से बेहाल लोग यदि वर्षा की पहली बौछार पर झूम उठें, तो यह भाव 'उत्साह' कविता के किस संदेश से मेल खाता है?", options: ["वर्षा से निराशा", "बादल से भय", "बादल की बरसात से जन-जन को राहत और नवजीवन मिलना", "ऋतुओं का बदलना व्यर्थ है"], answer: 2, explain: "कविता में बादल के बरसने से व्याकुल जन को शीतलता और उल्लास मिलता है।", level: 3 }
