    written: [
      { q: "'उत्साह' कविता का आरंभ कवि किस आह्वान के साथ करता है?", a: "कवि बादल को संबोधित करते हुए उससे गरजने का आह्वान करता है।", marks: 1 },
      { q: "निराला की दो रचनाओं के नाम लिखिए।", a: "परिमल और अनामिका (अन्य – राम की शक्ति पूजा)।", marks: 1 },
      { q: "'उत्साह' कविता में बादल को किन रूपों में चित्रित किया गया है?", a: "बादल एक ओर गरजकर क्रांति का प्रतीक है, दूसरी ओर तपती धरती पर बरसकर जीवन देता है। कवि उससे नई कविता का सृजन भी चाहता है।", marks: 3 },
      { q: "'अट नहीं रही है' कविता में फागुन की शोभा का वर्णन कैसे किया गया है?", a: "फागुन की शोभा सब ओर छाई है। पेड़ों पर नए पत्ते और रंग-बिरंगे फूल खिले हैं, हवा में सुगंध है। यह सौंदर्य इतना अधिक है कि कवि की दृष्टि हटती नहीं।", marks: 3 },
      { q: "कवि फागुन की सुंदरता से अपनी आँखें क्यों नहीं हटा पाता? 'अट नहीं रही है' के आधार पर बताइए।", a: "फागुन में वातावरण सुगंध, रंग और नई कोंपलों से भरा है। शोभा इतनी विपुल है कि कहीं समाती ही नहीं। इसलिए कवि मंत्रमुग्ध होकर उसे देखता रह जाता है।", marks: 3 },
      { q: "'उत्साह' कविता के आधार पर बादल के माध्यम से कवि द्वारा दिए गए संदेश को स्पष्ट कीजिए।", a: "कवि बादल को क्रांति और नवजीवन का प्रतीक मानता है। गर्मी से व्याकुल लोगों को वह बरसकर राहत देता है। साथ ही कवि चाहता है कि उसकी गर्जना से जड़ता टूटे और नई चेतना आए। बादल को वह कवि कहकर नई कविता में नवजीवन भरने को कहता है। इस प्रकार बादल आशा, उत्साह और परिवर्तन का संदेश देता है, जो पूरी कविता का मूल भाव है।", marks: 5, type: "long" },
      { q: "'अट नहीं रही है' कविता में निराला ने प्रकृति का मानवीकरण किस प्रकार किया है? उदाहरण सहित समझाइए।", a: "कवि फागुन को सजीव रूप में चित्रित करता है, मानो प्रकृति स्वयं उत्सव मना रही हो। पेड़ों पर नए पत्ते और फूल उसके श्रृंगार जैसे हैं और हवा में उसकी मादकता फैली है। शोभा इतनी अधिक है कि वह कहीं समाती नहीं। प्रकृति को मानवीय भाव देकर कवि सौंदर्य की जीवंत अनुभूति कराता है, इसीलिए पाठक भी फागुन के उल्लास में डूब जाता है।", marks: 5, type: "long" },
      { q: "प्रसंग: एक कविता में कवि आकाश में घुमड़ते काले बादलों को देखकर कहता है कि वे गरजें और नया जीवन बरसाएँ। उसे लगता है कि संसार गर्मी से उदास और बेचैन है।\n(i) कवि किससे आह्वान करता है?\n(ii) संसार किस कारण बेचैन है?\n(iii) कवि बादलों से क्या अपेक्षा करता है?", a: "(i) कवि बादल से आह्वान करता है।\n(ii) संसार गर्मी की तपन और जड़ता से व्याकुल है।\n(iii) वह चाहता है कि बादल गरजकर और बरसकर लोगों को राहत तथा नवजीवन दे।", marks: 4, type: "case" }
    ]
